\label{lem:global-hard-properties}
The function $H_{{\bf U},\mu}$ defined in
equation~(\ref{eq:global-hard-function}) satisfies
\begin{equation}
    H_{{\bf U},\mu}({\bf{0}})
    -\inf_{{\bf{x}}\in{\mathbb{R}}^d}H_{{\bf U},\mu}({\bf{x}})
    \le2T.
    \label{eq:global-hard-gap}
\end{equation}
Moreover, if there exists some $i\in[T]$ such that
$\left| [{\bf U}^\top\rho_R({\bf{x}})]_i\right|\le1$,
then it holds
\begin{equation}
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    \ge\frac14.
    \label{eq:global-hard-gradient}
\end{equation}
Furthermore, all ${\bf{x}}\in{\mathbb{R}}^d$, it holds
\begin{equation}
    \left\| \nabla^2H_{{\bf U},\mu}({\bf{x}}) \right\|
    \le
    240\left(
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    +\mu\log\frac1\mu
    \right).
    \label{eq:global-hard-curvature}
\end{equation}

\label{lem:hard-scaling}
For all $L_0,L_1,\epsilon>0$, we follow definitions in equations 
(\ref{eq:gate-functions})--(\ref{eq:global-hard-function}) by taking
\begin{equation}\label{eq:hard-scaling-parameters}
\mu:=\frac{\delta_0}{4\log({\mathrm{e}}/\delta_0)}, \quad
a:=\frac{7680\epsilon}{L_1}  \quad
b:=\frac{480}{L_1}, \quad \text{with}~~
\delta_0:= \min\left\{10^{-2}, \frac{L_0}{16L_1\epsilon} \right\}.
\end{equation}

Then the scaled function $f_{{\bf U}}({\bf{x}}):=aH_{{\bf U},\mu}\left({{\bf{x}}}/{b}\right)$ has the following properties.
\begin{enumerate}[label=(\alph*),leftmargin=0.65cm]
\item The function $f_{{\bf U}}$ is $(L_0,L_1)$-smooth.
\item The optimality gap holds $f_{{\bf U}}({\bf{0}})-\inf_{{\bf{x}}\in{\mathbb{R}}^d}f_{{\bf U}}({\bf{x}})    \le2aT$.
\item For given ${\bf{x}}=[x_1,\dots,x_T]\in{\mathbb{R}}^d$,  if there exists $i\in[T]$ such that
$\left|\left[{\bf U}^\top\rho_R({\bf{x}}/b)\right]_i\right|\le1$, then~\mbox{$\left\| \nabla f_{{\bf U}}({\bf{x}}) \right\| \ge4\epsilon$.}

\end{enumerate}

\label{def:probabilistic-zero-chain}
A stochastic gradient ${\bf{g}}:{\mathbb{R}}^T\times{\mathcal{Z}}\to{\mathbb{R}}^T$ is a probability-$\theta$ zero-chain with $\theta\in[0,1]$ if it holds
\begin{equation}
\mathbb P
\Big(\forall\,{\bf{y}}\in{\mathbb{R}}^T:
    \operatorname{prog}_0
    \big({\bf{g}}({\bf{y}};Z)\big) \le \operatorname{prog}_{1/4}({\bf{y}}),
    {\bf{g}}({\bf{y}};Z) ={\bf{g}}\big(\Pi_{\operatorname{prog}_{1/4}({\bf{y}})}({\bf{y}}); Z\big)
\Big) \ge 1-\theta,
\label{eq:prob-zero-chain-no-progress}
\end{equation}
and
\begin{equation}
\!\!\!\mathbb P_Z
\Big(\forall\,{\bf{y}}\in{\mathbb{R}}^T\!:
    \operatorname{prog}_0
    \big({\bf{g}}({\bf{y}};Z)\big) \le 1+\operatorname{prog}_{1/4}({\bf{y}}),
    {\bf{g}}({\bf{y}};Z) = {\bf{g}}\big(\Pi_{1+\operatorname{prog}_{1/4}({\bf{y}})}({\bf{y}}); Z\big)
\Big)=1.
\label{eq:prob-zero-chain-one-progress}
\end{equation}
Here, we denote $\Pi_s({\bf{y}})=[y_1,\dots,y_s,0,\dots,0]^\top$ for given ${\bf{y}}=[y_1,\dots,y_d]^\top\in{\mathbb{R}}^d$, where we let $\Pi_s({\bf{y}})={\bf{y}}$ when $s>T$ for convention.

\label{lem:oracle-validity}
For given $p\in(1,2]$ and $\sigma\ge0$, we let
\begin{equation}\label{eq:revelation-probability}
    q:=\begin{cases}
    1, & \sigma = 0, \\[0.25cm]
    \displaystyle{\min\left\{ 1,\, \left(\frac{2\cdot(3984)^p\epsilon^p}{\sigma^p}\right)^{\frac{1}{p-1}}
    \right\}}, & \sigma > 0.
    \end{cases}
\end{equation}
Then for all ${\bf{x}}\in{\mathbb{R}}^d$, it holds
\begin{align}
    {\mathbb{E}}_Z[\mathsf O_{f_{{\bf U}}}({\bf{x}};Z)] =\nabla f_{{\bf U}}({\bf{x}}),
    \qquad \text{and} \qquad
    {\mathbb{E}}_Z\left[\left\| \mathsf O_{f_{{\bf U}}}({\bf{x}};Z) -\nabla f_{{\bf U}}({\bf{x}}) \right\|^p \right] \le\sigma^p.
    \label{eq:oracle-p-moment}
\end{align}

\label{lem:randomized-hardness}

We let 
\begin{equation}\label{eq:rotation-dimension}
\delta\in(0,1), \qquad {\bf U}\sim\operatorname{Unif}(\operatorname{St}(d,T)),
\qquad\text{and}\qquad
d\ge \left\lceil T+32R^2\log\left(\frac{2T^2}{q\delta}\right) \right\rceil.
\end{equation}
Then for any randomized algorithm $\mathsf A\in\mathcal A_{\mathrm{rand}}$ associated with the oracle $\mathsf O_{f_{{\bf U}}}({\bf{x}};Z)$ defined in equations~(\ref{eq:hard-stochastic-oracle})
with probability at least $1-\delta$, it holds
\begin{equation}
    \left\| \nabla f_{{\bf U}}({\bf{x}}^{(t)}) \right\|
    \ge4\epsilon
    \label{eq:randomized-gradient-hardness}
\end{equation}
for all  $t\le(T-\log(2/\delta))/(2q)$,
where ${\bf{x}}^{(t)}$ is the $t$th query generated by randomized algorithm $\mathsf A$.

\label{thm:L1-lower-bound}
For any given $p\in(1,2]$, there exists numerical constant $\hat c>0$ such that for all $L_0,L_1,\Delta,\sigma>0$, and~$\epsilon\leq {\hat c} L_1\Delta$, it holds
\begin{equation}
\begin{aligned}
    m_{\epsilon}^{\mathrm{rand}}
    (L_0,L_1,\Delta,\sigma,p)
    \ge \Omega\left(
     \bigg(\frac{\sigma^{\frac{p}{p-1}}}{\epsilon^{\frac{p}{p-1}}}+1\bigg)\frac{L_1\Delta}{\epsilon}\right).
\end{aligned}
\label{eq:L1-lower-bound}
\end{equation}

\label{cor:joint-lower-bound}
For any given $p\in(1,2]$,
there exists numerical constant $c>0$ such that for all $L_0,L_1,\Delta,\sigma>0$, and $\epsilon\leq  c  \min\{\sqrt{L_0\Delta}, L_1\Delta\}$, it holds
\begin{equation}
   m_{\epsilon}^{\mathrm{rand}}(L_0,L_1,\Delta,\sigma,p)
\ge \Omega\left(\bigg(\frac{\sigma^{\frac{p}{p-1}}}{\epsilon^{\frac{p}{p-1}}}+1\bigg)\bigg(\frac{L_0\Delta}{\epsilon^2}+\frac{L_1\Delta}{\epsilon}\bigg)\right).
\label{eq:joint-lower-bound}
\end{equation}

\label{lem:gate-paired-properties}
For every $t\in{\mathbb{R}}$, the function $\psi$ defined in equation~(\ref{eq:gate-functions}) satisfies
\begin{align}
    \psi(t)+\psi(-t)
    &\le1,
    \label{eq:gate-pair-value}
    \\
    \psi'(t)+\psi'(-t)
    &\le4,
    \label{eq:gate-pair-first}
    \\
    |\psi''(t)|+|\psi''(-t)|
    &\le24.
    \label{eq:gate-pair-second}
\end{align}

\label{lem:radial-compression-properties}
For all ${\bf{x}}\in{\mathbb{R}}^d$, the mapping $\rho_R:{\mathbb{R}}^d\to{\mathbb{R}}^d$ defined in equation~(\ref{eq:radial-compression}) holds
\begin{align*}
    \left\| \rho_R({\bf{x}}) \right\|\le R, \qquad 
    \left\| D\rho_R({\bf{x}}) \right\|\le1, \qquad \text{and} \qquad 
    \left\| D^2\rho_R({\bf{x}}) \right\|\le\frac3R.
\end{align*}

Following \citet[Lemma 13 and its proof]{arjevani2023lower}, we directly obtain
\begin{equation}
    \left\| \rho_R({\bf{x}}) \right\|\le R

    \qquad\text{and}\qquad
    \left\| D\rho_R({\bf{x}}) \right\|\le1.
    \label{eq:radial-jacobian-bound}
\end{equation}
Here, we focus on the upper bound of $\left\| D^2\rho_R({\bf{x}}) \right\|$. We denote
\begin{equation}
    \alpha({\bf{x}}):=
    \left(1+\frac{\left\| {\bf{x}} \right\|^2}{R^2}\right)^{-1/2}.
    \label{eq:radial-alpha}
\end{equation}
Then we can write $\rho_R({\bf{x}})=\alpha({\bf{x}}){\bf{x}}$ and it holds  \citep[Lemma~13]{arjevani2023lower} 
\begin{equation}
    D\rho_R({\bf{x}})
    = \alpha({\bf{x}}){\bf I}_d - \frac{(\alpha({\bf{x}}))^3}{R^2}\cdot{\bf{x}}{\bf{x}}^\top.
    \label{eq:radial-jacobian}
\end{equation}
According to \citet[Lemma~13]{arjevani2023lower}, it holds
\begin{equation}
    \left\| D\rho_R({\bf{x}})-D\rho_R({\bf{y}}) \right\|
    \le\frac3R\left\| {\bf{x}}-{\bf{y}} \right\|
    \qquad\text{for all }{\bf{x}},{\bf{y}}\in{\mathbb{R}}^d.
    \label{eq:radial-jacobian-lipschitz}
\end{equation}
Since the mapping $\rho_R$ is twice continuously differentiable, for any ${\bf{h}},{\bf{k}}\in{\mathbb{R}}^d$, we have
\begin{align*}
    \left\| D^2\rho_R({\bf{x}})[{\bf{h}},{\bf{k}}] \right\|
    =
    \lim_{t\to0}
    \left\|
    \frac{
    \big(D\rho_R({\bf{x}}+t{\bf{k}})-D\rho_R({\bf{x}})\big){\bf{h}}
    }{t}
    \right\|\le
    \frac3R\left\| {\bf{h}} \right\|\left\| {\bf{k}} \right\|,

\end{align*}
where the inequality follows from equation~(\ref{eq:radial-jacobian-lipschitz}). Taking the supremum over all unit vectors ${\bf{h}}$ and ${\bf{k}}$, we achieve
\begin{equation}
    \left\| D^2\rho_R({\bf{x}}) \right\|
    \le\frac3R.
    \label{eq:radial-second-bound}
\end{equation}
This completes the proof.

Recall that equation~(\ref{eq:global-hard-function}) has defined
\[
    H_{{\bf U},\mu}({\bf{x}})
    =
    \bar f_T\big({\bf U}^\top\rho_R({\bf{x}})\big)
    +\frac{\mu}{2}\left\| {\bf{x}} \right\|^2
    \quad \text{with} \quad
    R=\frac{1000\sqrt T}{\mu}
    \quad\text{and}\quad
    \mu\in\left(0,\frac{1}{100}\right],
\]
where ${\bf U}=[{\bf{u}}_1,\ldots,{\bf{u}}_T]\in\operatorname{St}(d,T)$. 
Throughout the proof of this lemma, we denote
\begin{align*}
{\bf{y}}:={\bf U}^\top\rho_R({\bf{x}}).    
\end{align*}
and recall from equation~(\ref{eq:radial-alpha}) that $\rho_R({\bf{x}})=\alpha({\bf{x}}){\bf{x}}$. By Lemma~\ref{lem:hard-chain-properties}(b), we have
\begin{equation}
    \left\| \nabla\bar f_T({\bf{y}}) \right\|
    \le9\sqrt T                
    \qquad \text{and} \qquad
    \left\| \nabla^2\bar f_T({\bf{y}}) \right\|\le 58.
    \label{eq:global-chain-bounds}
\end{equation}

\paragraph{The optimality gap.}
Note that equation~(\ref{eq:radial-compression1}) implies $\rho_R({\bf{0}})={\bf{0}}$. 
Combining with equation~(\ref{eq:hard-chain-origin}), we obtain
\begin{align*}
H_{{\bf U},\mu}({\bf{0}})=\bar f_T({\bf{0}})=-1.     
\end{align*}
Moreover, the lower bound of $\bar f_T({\bf{y}})\ge-2T$ in equation~(\ref{eq:hard-chain-infimum}) implies
\[
    H_{{\bf U},\mu}({\bf{x}})
    \ge\bar f_T({\bf U}^\top\rho_R({\bf{x}}))
    \ge-2T
    \qquad\text{for all }{\bf{x}}\in{\mathbb{R}}^d.
\]
Combining above two results, we have
\begin{equation*}
    H_{{\bf U},\mu}({\bf{0}})
    -\inf_{{\bf{x}}\in{\mathbb{R}}^d}H_{{\bf U},\mu}({\bf{x}})
    \le -1+2T   \le2T.
\end{equation*}

\paragraph{The lower bound of the Hessian.}
According to the chain rule and equation~(\ref{eq:radial-jacobian}), the gradient of~$H_{{\bf U},\mu}$ has the form of
\begin{equation}
    \nabla H_{{\bf U},\mu}({\bf{x}})
    =
    D\rho_R({\bf{x}}){\bf U}\nabla\bar f_T({\bf{y}})
    +\mu{\bf{x}}.
    \label{eq:global-gradient-formula}
\end{equation}
Since we have assumed there exists some $i\in[T]$ such that
$|y_i|=\left| [{\bf U}^\top\rho_R({\bf{x}})]_i\right|\le1$, 
we denote
\begin{equation*}
    i_\star:=\min\{i\in[T]:|y_i|\le1\}.

\end{equation*}

If $i_\star=1$, then equation~(\ref{eq:hard-chain-gradient-coordinate}) and the non-negativity of $\psi'$ and $\phi$ from Lemma~\ref{lem:gate-properties}(b) and (c) imply
\begin{align}\label{eq:d-f-1-phi}    
    \frac{\partial\bar f_T({\bf{y}})}{\partial y_1}
    \le-\phi'(y_1).
\end{align}
If $i_\star\ge2$, the minimality of $i_\star$ gives $|y_{i_\star-1}|>1$. 
Hence, Lemma~\ref{lem:gate-properties}(a) implies
\begin{align*}
\psi(-y_{i_\star-1})+\psi(y_{i_\star-1})=1.
\end{align*}
Substituting the above result into equation~(\ref{eq:hard-chain-gradient-coordinate}) also yields equation~(\ref{eq:d-f-1-phi}). 
Thus, Lemma~\ref{lem:gate-properties}(d) implies
\begin{equation}
    \frac{\partial\bar f_T({\bf{y}})}{\partial y_{i_\star}}
    \le-\phi'(y_{i_\star})
    <-\frac25.
    \label{eq:global-unfinished-gradient}
\end{equation}
In the case of $\left\| {\bf{x}} \right\|\ge20\sqrt T/\mu$, we apply equation~(\ref{eq:global-gradient-formula}), (\ref{eq:radial-jacobian-bound}), and \ref{eq:global-chain-bounds} to achieve
\begin{align}\label{eq:global-large-radius-lower}
\begin{split}  
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    &\ge 20\sqrt{T}
    -\left\| D\rho_R({\bf{x}}){\bf U}\nabla\bar f_T({\bf{y}}) \right\| \\
    &\ge 20\sqrt{T}
    -\left\| \nabla\bar f_T({\bf{y}}) \right\| \\
    &\ge  20\sqrt{T} -9\sqrt T,    \\
    &\ge  11.   
\end{split}
\end{align}
In the case of $\left\| {\bf{x}} \right\|<20\sqrt T/\mu$. The setting $R=1000\sqrt T/\mu$ implies $\left\| {\bf{x}} \right\|/R<1/50$. Therefore, equation~(\ref{eq:radial-alpha}) implies
\begin{equation}
    \alpha({\bf{x}})>
    \left(1+\frac1{2500}\right)^{-1/2}
    >\frac{99}{100}
    \qquad \text{and} \qquad
    \frac1{\alpha({\bf{x}})}<\frac{101}{100}.
    \label{eq:global-alpha-near}
\end{equation}
Let ${\bf{u}}_{i_\star}\in{\mathbb{R}}^T$ be the $i_\star$th column of ${\bf U}$.
Recall that ${\bf U}^\top{\bf U}={\bf I}_T$, we then apply equations (\ref{eq:global-gradient-formula}) and~(\ref{eq:radial-jacobian}) to~give
\begin{align}
    \langle{\bf{u}}_{i_\star},\nabla H_{{\bf U},\mu}({\bf{x}})\rangle
    = 
    \frac{\alpha({\bf{x}})\partial\bar f_T({\bf{y}})}{\partial y_{i_\star}}
    - \frac{(\alpha({\bf{x}}))^3}{R^2}
    \langle{\bf{u}}_{i_\star},{\bf{x}}\rangle
    \langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle
    + \mu\langle{\bf{u}}_{i_\star},{\bf{x}}\rangle.
    \label{eq:global-directional-gradient}
\end{align}
Note that the definition of $i_\star$ indicates  $y_{i_\star}=\alpha({\bf{x}})\langle{\bf{u}}_{i_\star},{\bf{x}}\rangle$ and $|y_{i_\star}|\le1$, which results
\begin{equation}
    |\langle{\bf{u}}_{i_\star},{\bf{x}}\rangle|
    \le\frac1{\alpha({\bf{x}})}.
    \label{eq:global-coordinate-bound}
\end{equation}
For the second term on the right-hand side of inequality (\ref{eq:global-alpha-near}), we have
\begin{align}\label{eq:global-compression-error}
\begin{split}    
& \frac{(\alpha({\bf{x}}))^3}{R^2}
\left| \langle{\bf{u}}_{i_\star},{\bf{x}}\rangle
\langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle \right|  
\le \frac{(\alpha({\bf{x}}))^3}{R^2}
\left| \langle{\bf{u}}_{i_\star},{\bf{x}}\rangle \right|
\left\| {\bf{x}}\right\| \left\|{\bf U}\nabla\bar f_T({\bf{y}}) \right\|  \\
\le & \frac{(\alpha({\bf{x}}))^2\left\| {\bf{x}}\right\| }{R^2}
\left\|{\bf U}\nabla\bar f_T({\bf{y}}) \right\| 

\le \frac{9\sqrt T\left\| {\bf{x}} \right\|}{R^2}
\leq \frac{9\sqrt T(20\sqrt T/\mu)}{(1000\sqrt T/\mu)^2}
=\frac{\mu}{5000}\le \frac{2}{10^{6}}.
\end{split}
\end{align}
where the first inequality is based on Cauchy--Schwarz inequality,
the second inequality is based on equation~(\ref{eq:global-coordinate-bound}),
the third inequality is based on equation (\ref{eq:global-chain-bounds}) and the definition (\ref{eq:radial-alpha}),
and the last inequality is based on the condition $\left\| {\bf{x}} \right\|<20\sqrt T/\mu$ and the setting $R=1000\sqrt T/\mu$.
For the last term on the right-hand side of inequality (\ref{eq:global-alpha-near}), equation~(\ref{eq:global-alpha-near}) and the setting $\mu\le10^{-2}$ implies
\begin{align}\label{eq:global-regularizer-error}
    \mu|\langle{\bf{u}}_{i_\star},{\bf{x}}\rangle|
    &\le\frac{\mu}{\alpha({\bf{x}})}
    <\frac{101}{100}\mu \leq \frac{101}{10000}
\end{align}
Combining equations (\ref{eq:global-unfinished-gradient}), (\ref{eq:global-compression-error}), (\ref{eq:global-regularizer-error}), and (\ref{eq:global-alpha-near}) with equation~(\ref{eq:global-directional-gradient}), we obtain
\begin{align*}
    \left|
    \langle{\bf{u}}_{i_\star},\nabla H_{{\bf U},\mu}({\bf{x}})\rangle
    \right|
    \ge \frac{2\alpha({\bf{x}})}5 - 2\times10^{-6} -\frac{101}{10000}
    > \frac25\cdot\frac{99}{100}    
    -2\times10^{-6} -\frac{101}{10000} 
    > \frac14.

\end{align*}
Since we have $\left\| {\bf{u}}_{i_\star} \right\|=1$, the Cauchy--Schwarz inequality yields
\begin{equation}
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    \ge
    \left|
    \langle{\bf{u}}_{i_\star},\nabla H_{{\bf U},\mu}({\bf{x}})\rangle
    \right|
    >\frac14.
    \label{eq:global-gradient-small-radius}
\end{equation}

Combining equation~(\ref{eq:global-large-radius-lower}) and equation~(\ref{eq:global-gradient-small-radius}), we conclude that whenever there exists some $i\in[T]$ such that $|[{\bf U}^\top\rho_R({\bf{x}})]_i|\le1$, it holds $\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|\ge 1/4$.

\paragraph{The upper bound for the Hessian.}
We now establish the gradient-dependent upper bound for the Hessian. 
For all vectors ${\bf{h}},{\bf{k}}\in{\mathbb{R}}^d$, the chain rule implies
\begin{align}
\begin{split}\label{eq:global-second-chain-rule}    
    D^2H_{{\bf U},\mu}({\bf{x}})[{\bf{h}},{\bf{k}}]
&=  \left\langle
    \nabla^2\bar f_T({\bf{y}})
    {\bf U}^\top D\rho_R({\bf{x}})[{\bf{h}}],
    {\bf U}^\top D\rho_R({\bf{x}})[{\bf{k}}]
    \right\rangle \\
&~~\quad + \left\langle
    {\bf U}\nabla\bar f_T({\bf{y}}),
    D^2\rho_R({\bf{x}})[{\bf{h}},{\bf{k}}]
    \right\rangle + \mu\langle{\bf{h}},{\bf{k}}\rangle.
\end{split}
\end{align}
Taking the supremum on ${\bf{h}}$ and ${\bf{k}}$ over the unit ball and and using the fact $\left\| {\bf U} \right\|=1$, we obtain
\begin{align}\label{eq:global-uniform-hessian}
\begin{split}    
     \left\| \nabla^2H_{{\bf U},\mu}({\bf{x}}) \right\|
\le &{} \left\| \nabla^2\bar f_T({\bf{y}}) \right\|\left\| D\rho_R({\bf{x}}) \right\|^2+\left\| \nabla\bar f_T({\bf{y}}) \right\|\left\| D^2\rho_R({\bf{x}}) \right\|+\mu \\
\le &{}  58+\frac{27\sqrt T}{R}+\mu 
\leq 58+\frac{1027\mu}{1000}  < 59,
\end{split}
\end{align}
where the second inequality is based on equations (\ref{eq:global-chain-bounds}), (\ref{eq:radial-jacobian-bound}), and (\ref{eq:radial-second-bound}), the second last two inequalities are based on the settings $R=1000\sqrt T/\mu$ and $\mu\le10^{-2}$.

If there exists some $i\in[T]$ such that $|y_i|\le1$.
According to equation~(\ref{eq:global-hard-gradient}) from Lemma \ref{lem:global-hard-properties}, we have $\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|\ge1/4$. Combining this with equation~(\ref{eq:global-uniform-hessian}) and the setting $\mu<1$ yields
\begin{equation}
    \left\| \nabla^2H_{{\bf U},\mu}({\bf{x}}) \right\|
    <59
    <240\cdot\frac14
    \le240\left(
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    +\mu\log\frac1\mu
    \right).
    \label{eq:global-curvature-case-one}
\end{equation}

We then focus on the case that $|y_i|>1$ holds for all $i\in[T]$.
If $\left\| {\bf{x}} \right\|\ge20\sqrt T/\mu$, then equations~(\ref{eq:global-uniform-hessian}) and (\ref{eq:global-large-radius-lower}) imply
\begin{align}
    \left\| \nabla^2H_{{\bf U},\mu}({\bf{x}}) \right\|
    &<59\le 240\cdot 11
    \le 240 \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|\leq 240\left(\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|+\mu\log \frac1\mu
    \right). \label{eq:global-curvature-case-two}        
\end{align}
If $\left\| {\bf{x}} \right\|<20\sqrt T/\mu$, then equation~(\ref{eq:global-alpha-near}) gives
\begin{align*}                    
    \alpha({\bf{x}})>\frac{99}{100} \qquad\text{and}\qquad 
    \frac{1}{\alpha({\bf{x}})}<\frac{100}{99}.
\end{align*}
The condition $|y_i|>1$ holds for all $i\in[T]$ indicates that we can combine equation~(\ref{eq:hard-chain-saturated-gradient}) and  Lemma~\ref{lem:gate-properties}(c) to achive
\begin{equation}
    \left\| \nabla^2\bar f_T({\bf{y}}) \right\|
    =
    \max_{i\in[T]}|\phi''(y_i)|
    \le2\max_{i\in[T]}\phi'(y_i).
    \label{eq:global-completed-hessian-bound}
\end{equation}
We denote the index $j\in[T]$ such that $\phi'(y_j)=\max_{i\in[T]}\phi'(y_i)$ and analyze the right-hand side of inequality (\ref{eq:global-completed-hessian-bound}) by the following two cases.
\begin{enumerate}
\item If $|y_j|\ge\log(1/\mu)$, then Lemma~\ref{lem:gate-properties}(c) implies
\begin{equation}
    \max_{i\in[T]}\phi'(y_i)
    =
    \operatorname{sech}^2(y_j)
    \le4\mathrm e^{-2|y_j|}
    \le4\mu^2
    \le\mu\log\frac1\mu,
    \label{eq:global-phi-large-coordinate}
\end{equation}
where the first inequality follows from $\cosh t\ge\mathrm e^{|t|}/2$, and the last inequality uses $\mu\le10^{-2}$.
\item If $|y_j|<\log(1/\mu)$, then the identity $y_j=\alpha({\bf{x}})\langle{\bf{u}}_j,{\bf{x}}\rangle$ implies
\begin{equation}
    |\langle{\bf{u}}_j,{\bf{x}}\rangle|
    <
    \frac{\log(1/\mu)}{\alpha({\bf{x}})}.
    \label{eq:global-log-coordinate}
\end{equation}
Following the derivation of equation~(\ref{eq:global-directional-gradient}) by replacing ${\bf{u}}_{i_\star}$ with ${\bf{u}}_{j}$, we obtain
\begin{align*}
    \langle {\bf{u}}_j ,\nabla H_{{\bf U},\mu}({\bf{x}})\rangle  
    &=\frac{\alpha({\bf{x}})\partial\bar f_T({\bf{y}})}{\partial y_{j}}-\frac{(\alpha({\bf{x}}))^3}{R^2}\langle{\bf{u}}_j,{\bf{x}}\rangle\langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle
    +\mu\langle{\bf{u}}_j,{\bf{x}}\rangle \\
    &=-\alpha({\bf{x}})\phi'(y_j)-\frac{(\alpha({\bf{x}}))^3}{R^2}\langle{\bf{u}}_j,{\bf{x}}\rangle\langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle
    +\mu\langle{\bf{u}}_j,{\bf{x}}\rangle,
\end{align*}
where the last step is based on equation~(\ref{eq:hard-chain-saturated-gradient}).
Since we have $\phi'(y_j)=\max_{i\in[T]}\phi'(y_i)$ and~$\left\| {\bf{u}}_j \right\|=1$, applying the triangle inequality on above equation implies
\begin{align}\label{eq:alpha-max-phi-yi}
    \alpha({\bf{x}})\max_{i\in[T]}\phi'(y_i)\le\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|+\frac{(\alpha({\bf{x}}))^3}{R^2}|\langle{\bf{u}}_j,{\bf{x}}\rangle|
    \left|\langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle\right| + \mu|\langle{\bf{u}}_j,{\bf{x}}\rangle|.
\end{align}
For the second term on the right-hand side of equation~(\ref{eq:alpha-max-phi-yi}),
applying Cauchy--Schwarz inequality, equation~(\ref{eq:global-chain-bounds}) with the fact ${\bf U}^\top{\bf U}={\bf I}_T$ imply
\begin{align*}
|\langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle|
\le \left\| {\bf{x}} \right\|\left\| \nabla\bar f_T({\bf{y}}) \right\|\le9\sqrt T\left\| {\bf{x}} \right\|.    
\end{align*}
Combining with equation~(\ref{eq:global-log-coordinate}), we obtain
\begin{align}\label{eq:alpha-max-phi-yi-1}
\begin{split}    
   & \frac{(\alpha({\bf{x}}))^3}{R^2}|\langle{\bf{u}}_j,{\bf{x}}\rangle|\left|\langle{\bf{x}},{\bf U}\nabla\bar f_T({\bf{y}})\rangle\right| \\
\le & \frac{9(\alpha({\bf{x}}))^2\sqrt T\left\| {\bf{x}} \right\|\log(1/\mu)}{R^2} \\
< & \frac{9\mu\log(1/\mu)}{50000}<\frac{\mu\log(1/\mu)}{5000},
\end{split}
\end{align}
where the second inequality follows from $\alpha({\bf{x}})\le1$, $\left\| {\bf{x}} \right\|<20\sqrt T/\mu$, and $R=1000\sqrt T/\mu$.
Substituting equations (\ref{eq:alpha-max-phi-yi-1}) and (\ref{eq:global-log-coordinate}) into equation~(\ref{eq:alpha-max-phi-yi}), we obtain
\begin{align}
    \alpha({\bf{x}})\max_{i\in[T]}\phi'(y_i)
    \le




    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    +
    \left(\frac1{5000}+\frac1{\alpha({\bf{x}})}
    \right)\mu\log\frac1\mu.
    \label{eq:global-phi-start-bound}
\end{align}
Dividing equation~(\ref{eq:global-phi-start-bound}) by $\alpha({\bf{x}})>0$ and applying equation~(\ref{eq:global-alpha-near}), we obtain
\begin{align}\label{eq:global-phi-small-coordinate}
\begin{split}    
    \max_{i\in[T]}\phi'(y_i)
    &\le \frac1{\alpha({\bf{x}})}
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|+
    \left(\frac1{5000\alpha({\bf{x}})} + \frac1{(\alpha({\bf{x}}))^2} \right)\mu\log\frac1\mu \\
    &\le 2\left(
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    +\mu\log\frac1\mu
    \right).
\end{split}
\end{align}
\end{enumerate}
Combining equations (\ref{eq:global-phi-large-coordinate}) and (\ref{eq:global-phi-small-coordinate}), we conclude that
\begin{equation}
    \max_{i\in[T]}\phi'(y_i)
    \le
    2\left(
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    +\mu\log\frac1\mu
    \right).
    \label{eq:global-max-phi-bound}
\end{equation}
We now return to the bound of Hessian. The first inequality in equation~(\ref{eq:global-uniform-hessian}) implies
\begin{align}
\begin{split}
    \left\| \nabla^2H_{{\bf U},\mu}({\bf{x}}) \right\|
    &\le
    \left\| \nabla^2\bar f_T({\bf{y}}) \right\|\left\| D\rho_R({\bf{x}}) \right\|^2+\left\| \nabla\bar f_T({\bf{y}}) \right\|\left\| D^2\rho_R({\bf{x}}) \right\|+\mu\\
    &\le2\max_{i\in[T]}\phi'(y_i)+\frac{27\sqrt T}{R}+\mu
    \\
    &\le4\left(\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|+\mu\log\frac1\mu\right)+\frac{1027}{1000}\mu
    \\
    &\le\frac{5027}{1000}\left(\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|+\mu\log\frac1\mu\right)
    \\
    &<240\left(\left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|+\mu\log\frac1\mu\right),
\end{split}
\label{eq:global-curvature-case-three}
\end{align}
where the second inequality is based on 
equations (\ref{eq:global-completed-hessian-bound}),  
(\ref{eq:radial-jacobian-bound}), (\ref{eq:global-chain-bounds}),and  (\ref{eq:radial-second-bound});
the third inequality inequality follows from equation~(\ref{eq:global-max-phi-bound}) and setting $R=1000\sqrt T/\mu$;
the inequality uses the fact $\mu\le10^{-2}$ which implies $\mu\le\mu\log(1/\mu)$.

Combining equations (\ref{eq:global-curvature-case-one}), (\ref{eq:global-curvature-case-two}), and (\ref{eq:global-curvature-case-three}), we conclude that for every ${\bf{x}}\in{\mathbb{R}}^d$, it holds
\begin{equation*}
    \left\| \nabla^2H_{{\bf U},\mu}({\bf{x}}) \right\|
    \le
    240\left(
    \left\| \nabla H_{{\bf U},\mu}({\bf{x}}) \right\|
    +\mu\log\frac1\mu
    \right).
\end{equation*}
This completes the proof.

\label{eq:chi-flat-derivative}
Based on the definition of $\chi(t)$ in equation~(\ref{eq:masking-functions}), for all $t\in{\mathbb{R}}$, it holds 
\begin{align} \label{eq:chi-derivative-bound}
0\le\chi(t)\le1
\qquad\text{and}\qquad
|\chi'(t)|^2\le14400\bigl(1-(\chi(t))^2\bigr).    
\end{align}

According to definition of $\chi(t)$ in equation~(\ref{eq:masking-functions}), it holds
\begin{equation}\label{eq:chi-flat-values}
    \chi(t)= \begin{cases}
    1, & \text{if }|t|\le\dfrac14, \\[0.3cm]
    0, & \text{if }|t|\ge\dfrac12,
    \end{cases}
\end{equation}
which implies 
\begin{equation}\label{eq:chi-flat-values2}
    \chi'(t)=0
    \quad\text{whenever}~~
    |t|\le\frac14
    ~~\text{ or }~~|t|\ge\frac12.
\end{equation}
Moreover, the bounds on $S$ established in the proof of Lemma~\ref{lem:gate-properties}(b) imply
\begin{equation}
    0\le\chi(t)\le1
    \qquad\text{for all }t\in{\mathbb{R}}.
    \label{eq:chi-range}
\end{equation}
Combining equations (\ref{eq:chi-flat-values}) and (\ref{eq:chi-range}) indicates equation~(\ref{eq:chi-derivative-bound}) holds whenever $|t|\le1/4$ or~$|t|\ge1/2$. 

It remains to prove equation~(\ref{eq:chi-derivative-bound}) holds when $|t|\in(1/4,1/2)$.
We let 
\begin{align*}
u:=4|t|-1\in(0,1).     
\end{align*}
for $t$ such that $|t|\in(1/4,1/2)$.
Applying the chain rule and equation~(\ref{eq:S-prime}) give
\begin{align*}
    |\chi'(t)| = 4S'(u) = 120u^2(1-u)^2.    
\end{align*}
Moreover, the definition of $S(u)$ in equation~(\ref{eq:gate-S}) gives
\[
    S(u)=u^3(10-15u+6u^2)\ge u^3= u^3(3(1-u)(3-2u)+1) \geq u^3,
\]
Hence, combining the facts $u\in(0,1)$ and $S(u)\in(0,1)$ with above two results leads to 
\begin{align*}
    |\chi'(t)|^2
    &=14400u^4(1-u)^4
    \nonumber\\
    &\le14400u^3
    \le14400S(u)(2-S(u))
    \nonumber\\
    &=14400\bigl(1-\chi(t)^2\bigr).
\end{align*}
whenever $|t|\in(1/4,1/2)$.
Thus equation~(\ref{eq:chi-derivative-bound}) holds for every $t\in{\mathbb{R}}$.

The definition $\Theta_i({\bf{y}}):=\prod_{k=i}^{T}\chi(y_k)$ implies
\begin{equation}
    \frac{\partial\Theta_i({\bf{y}})}{\partial y_j}
    =
    \begin{cases}
        0, & j<i,\\[0.1cm]
        \displaystyle
        \chi'(y_j)
        \prod_{\substack{k=i\\k\ne j}}^{T}
        \chi(y_k), & j\ge i.
    \end{cases}
    \label{eq:theta-coordinate-derivative}
\end{equation}
Consequently, Lemma \ref{eq:chi-flat-derivative} implies 
\begin{align*}
    \left\| \nabla\Theta_i({\bf{y}}) \right\|^2
    = \sum_{j=i}^{T}
    |\chi'(y_j)|^2
    \prod_{\substack{k=i\\k\ne j}}^{T}
    \chi(y_k)^2
    \le 14400\sum_{j=i}^{T}
    \bigl(1-\chi(y_j)^2\bigr)
    \prod_{\substack{k=i\\k\ne j}}^{T}
    \chi(y_k)^2 \le14400. 
\end{align*}
Taking square roots on above result yields
\begin{equation*}
    \left\| \nabla\Theta_i({\bf{y}}) \right\|\le120,
\end{equation*}
which completes the proof.

The assumption on the index $s$ means
\begin{equation}
    |y_{s+1}|,\ldots,|y_T|\le\frac14.
    \label{eq:information-tail-assumption}
\end{equation}
According to equations (\ref{eq:masking-functions}) and (\ref{eq:chi-flat-values}), we have
\begin{equation*}
    \chi(y_k)=1
    \qquad \text{and}\qquad
    \chi'(y_k)=0
    \qquad \text{for all}~~k=s+1,\ldots,T.

\end{equation*}
Consequently, the definition of $\Theta_i({\bf{y}})$ in equation~(\ref{eq:masking-functions}) implies
\begin{equation}
    \Theta_i({\bf{y}})
    =\begin{cases}
    \displaystyle{\prod_{k=i}^{s}\chi(y_k)},  & \text{if}~i\le s+1, \\[0.35cm]
    1 & \text{otherwise}.
    \end{cases}
    \label{eq:theta-tail-reduction}
\end{equation}
Hence, we have
\begin{equation}
    \Theta_{s+1}({\bf{y}})=1,
    \qquad\text{and}\qquad
    \nabla\Theta_{s+1}({\bf{y}})={\bf{0}},
    \label{eq:theta-s-plus-one}
\end{equation}
It also holds
\begin{equation}
    \frac{\partial\Theta_i({\bf{y}})}{\partial y_j}=0 \qquad
    \text{whenever} \quad i\le s+1 \quad\text{and}\quad j\ge s+1.
    \label{eq:theta-no-tail-derivative}
\end{equation}
Moreover, for all $i\ge s+2$, condition equation~(\ref{eq:information-tail-assumption}) gives $|y_{i-1}|\le1/4$ and $|y_i|\le1/4$. 
Hence, Lemma~\ref{lem:gate-properties}(a) implies
\[
    \psi(y_{i-1})=\psi(-y_{i-1})=\psi'(y_{i-1})=\psi'(-y_{i-1})=0.
\]
Hence, the definition of $A_i({\bf{y}})$ in equation~(\ref{eq:hard-zero-chain}) implies
\begin{equation}
    A_i({\bf{y}})=0
    \qquad\text{and}\quad
    \nabla A_i({\bf{y}})={\bf{0}}
    \qquad \text{for all}~~i\ge s+2.
    \label{eq:A-tail-zero}
\end{equation}

\paragraph{The proof of statement (a).}
For $Z=0$, equations~(\ref{eq:stochastic-chain}) and (\ref{eq:masking-Q-decomposition}) give
\begin{equation*}
    \bar F_T({\bf{y}};0)
    =
    \sum_{i=1}^{T}
    A_i({\bf{y}})\bigl(1-\Theta_i({\bf{y}})\bigr).

\end{equation*}
Combining with equations (\ref{eq:theta-s-plus-one}) and (\ref{eq:A-tail-zero}), we have
\begin{equation}
    \nabla\bar F_T({\bf{y}};0)
    =
    \sum_{i=1}^{s}
    \nabla\left(
    A_i({\bf{y}})\bigl(1-\Theta_i({\bf{y}})\bigr)
    \right).
    \label{eq:F-zero-first-s}
\end{equation}
Under condition (\ref{eq:information-tail-assumption}), 
we know that equation~(\ref{eq:hard-zero-chain}) indicates
all functions $A_1,\dots,A_s$ only depend on  $y_1,\ldots,y_s$,
and equations (\ref{eq:theta-tail-reduction}) and (\ref{eq:theta-no-tail-derivative}) imply that the function values and the gradients of all~$\Theta_1,\dots,\Theta_s$ only depend on the $y_1,\ldots,y_s$. 
Hence, equation~(\ref{eq:F-zero-first-s}) yields
\begin{align*}
    \operatorname{supp}
    \bigl(\nabla\bar F_T({\bf{y}};0)\bigr)
    \subseteq[s]
    \qquad\text{and}\qquad
    \nabla\bar F_T({\bf{y}};0)
    =\nabla\bar F_T(\Pi_s({\bf{y}});0).
\end{align*}

\paragraph{The proof of statement (b).}
For $Z=1$, equations~equation~(\ref{eq:stochastic-chain}) and equation~(\ref{eq:masking-Q-decomposition}) give
\begin{equation*}
    \bar F_T({\bf{y}};1)
    =\sum_{i=1}^{T} A_i({\bf{y}})\left(1+\left(\frac1q-1\right)\Theta_i({\bf{y}})\right).
\end{equation*}
Recall that equation~(\ref{eq:A-tail-zero}) indicates that all terms with $i\ge s+2$ in above summation have zero gradient. Thus, it holds
\begin{equation}
    \nabla\bar F_T({\bf{y}};1)
    =
    \sum_{i=1}^{s+1}
    \nabla\left(
    A_i({\bf{y}})
    \left(
    1+\left(\frac1q-1\right)\Theta_i({\bf{y}})
    \right)
    \right).
    \label{eq:F-one-first-s-plus-one}
\end{equation}
Under condition (\ref{eq:information-tail-assumption}), 
we know equation~(\ref{eq:hard-zero-chain}) implies all function $A_1,\dots,A_{s+1}$ only depends on~$y_1,\dots,y_{s+1}$,
and equations (\ref{eq:theta-tail-reduction}), (\ref{eq:theta-s-plus-one}), and (\ref{eq:theta-no-tail-derivative}) imply that the function values and the gradients of $\Theta_1,\dots,\Theta_{s+1}$ only depend on $y_1,\dots,y_{s+1}$. 
Hence, equation~(\ref{eq:F-one-first-s-plus-one}) yields
\begin{align*}
    \operatorname{supp}
    \bigl(\nabla\bar F_T({\bf{y}};1)\bigr)
    \subseteq[s+1]
    \qquad\text{and}\qquad
    \nabla\bar F_T({\bf{y}};1)
    =\nabla\bar F_T(\Pi_{s+1}({\bf{y}});1).
\end{align*}

We let ${\bf{y}}:={\bf U}^\top\rho_R({\bf{x}}/b)$. By the chain rule, the stochastic oracle defined in equation~(\ref{eq:hard-stochastic-oracle}) has the form of 
\begin{equation*}
    \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)
    =
    \frac{a}{b}
    D\rho_R\left(\frac{{\bf{x}}}{b}\right)^\top
    {\bf U}\nabla\bar F_T({\bf{y}};Z)
    +\frac{a\mu{\bf{x}}}{b^2}
\end{equation*}
Combining the above result  with equations (\ref{eq:global-hard-function}), (\ref{eq:stochastic-chain}), (\ref{eq:scaled-hessian-formula}), and (\ref{eq:global-gradient-formula}), we obtain
\begin{equation}
    \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)
    = \nabla f_{{\bf U}}({\bf{x}}) + 
    \frac{a}{b}\left(\frac Zq-1\right)
    D\rho_R\left(\frac{{\bf{x}}}{b}\right)^\top
    {\bf U}\nabla Q_T({\bf{y}}).
    \label{eq:oracle-noise-exact}
\end{equation}

\paragraph{Unbiasedness.}
Since $Z\sim\operatorname{Bernoulli}(q)$ with $q\in(0,1]$, taking the expectation on equation~(\ref{eq:oracle-noise-exact}) achieves
\begin{equation}
    {\mathbb{E}}_Z[\mathsf O_{f_{{\bf U}}}({\bf{x}};Z)]
    =
    \nabla f_{{\bf U}}({\bf{x}}).
    \label{eq:oracle-unbiased-proof}
\end{equation}

\paragraph{Bound on the $p$th central moment.}
Combing equations (\ref{eq:oracle-noise-exact}), (\ref{eq:radial-jacobian-bound}), and (\ref{eq:Q-gradient-bound}), we have
\begin{align}\label{eq:oracle-noise-pointwise}
\begin{split}    
    \left\| \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)-\nabla f_{{\bf U}}({\bf{x}}) \right\|
    &\le
    \frac{a}{b}
    \left|\frac Zq-1\right|
    \left\| D\rho_R({\bf{x}}/b) \right\|
    \left\| {\bf U} \right\|
    \left\| \nabla Q_T({\bf{y}}) \right\| \\
    &\le
    16\epsilon\cdot249
    \left|\frac Zq-1\right|
    =
    3984\epsilon
    \left|\frac Zq-1\right|,
\end{split}
\end{align}
where we use the setting $\left\| {\bf U} \right\|=1$ and $a/b=16\epsilon$ from equation~(\ref{eq:hard-scaling-parameters}).
Since $Z\sim\operatorname{Bernoulli}(q)$ and~$p\in(1,2]$, we have
\begin{align}
    {\mathbb{E}}_Z\left[\left|\frac Zq-1\right|^p\right]
    &=
    (1-q)^p q^{1-p}+1-q\le
    q^{1-p}+1
    \le2q^{1-p},
    \label{eq:oracle-bernoulli-upper}
\end{align}
where the inequalities follow from $0<q\le1$ and $p>1$. Consequently, combining equations (\ref{eq:oracle-noise-pointwise}) and (\ref{eq:oracle-bernoulli-upper}) imply
\begin{equation}
    {\mathbb{E}}_Z\left[
    \left\| \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)-\nabla f_{{\bf U}}({\bf{x}}) \right\|^p
    \right]
    \le
    2(3984\epsilon)^p q^{1-p}.
    \label{eq:oracle-noise-before-q}
\end{equation}
If $q<1$, then $\sigma>0$ and the definition of $q$ gives $q^{p-1}=2(3984)^p\epsilon^p\sigma^{-p}$.
Substituting this identity into equation~(\ref{eq:oracle-noise-before-q}), we obtain
\begin{align}
    {\mathbb{E}}_Z\left[
    \left\| \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)-\nabla f_{{\bf U}}({\bf{x}}) \right\|^p
    \right]
    \le 2(3984\epsilon)^p q^{1-p}=2(3984\epsilon)^p\cdot\frac{\sigma^p}{2(3984)^p\epsilon^p}=\sigma^p.
    \label{eq:oracle-moment-q-less-one}
\end{align}
If $q=1$, then $Z=1$ almost surely. Hence, equation~(\ref{eq:oracle-unbiased-proof}) implies
\begin{equation}
    {\mathbb{E}}_Z\left[
    \left\| \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)-\nabla f_{{\bf U}}({\bf{x}}) \right\|^p
    \right]
    =0\le\sigma^p.
    \label{eq:oracle-moment-q-one}
\end{equation}
Combining equation~(\ref{eq:oracle-moment-q-less-one}) and equation~(\ref{eq:oracle-moment-q-one}), we conclude that for every ${\bf{x}}\in{\mathbb{R}}^d$,
\begin{equation}
    {\mathbb{E}}_Z\left[
    \left\| \mathsf O_{f_{{\bf U}}}({\bf{x}};Z)-\nabla f_{{\bf U}}({\bf{x}}) \right\|^p
    \right]
    \le\sigma^p.
    \label{eq:oracle-p-moment-proof}
\end{equation}

We follow the setting of $a$, $b$, $\mu$, and $R$ by equations (\ref{eq:hard-scaling-parameters}) and (\ref{eq:global-hard-function}).
For $\epsilon\le\hat c L_1\Delta$ with $\hat c=1/122880$, we let
