\end{align}
where the inequality follows from $\max\{u,v\}\ge(u+v)/2$ for $u,v\ge0$ and
$2^{-\frac1{p-1}}(3984)^{-\frac p{p-1}}\le1$.
For any given $p\in(1,2]$, combining equations (\ref{eq:lower-via-N}), (\ref{eq:calibrated-N-lower}), (\ref{eq:calibrated-T-lower}), and (\ref{eq:calibrated-q-lower}) achieves
\begin{align*}
    m_{\epsilon}^{\mathrm{rand}}
    (L_0,L_1,\Delta,\sigma,p)
    \ge
    \Omega\left(\left(
    \frac{\sigma^{\frac p{p-1}}}{\epsilon^{\frac p{p-1}}}+1
    \right)
    \frac{L_1\Delta}{\epsilon}\right).
\end{align*}

This finishes the proof.

For any given $p\in(1,2]$, recall that \citet[Theorem 3.3]{liu2025nonconvex} have provided a lower bound for standard smooth optimization under the $p$-BCM condition, i.e.,  there exists $\tilde c>0$ such that
for all $L_0,\Delta,\sigma>0$, and~$\epsilon\le\tilde c\sqrt{L_0\Delta}$, it holds
\begin{equation*}
    m_{\epsilon}^{\mathrm{rand}}(L_0,0,\Delta,\sigma,p)
    \ge \Omega\left(\bigg(\frac{\sigma^{\frac{p}{p-1}}}{\epsilon^{\frac{p}{p-1}}}+1 \bigg)\frac{L_0\Delta}{\epsilon^2}\right),
\end{equation*}
Since $\mathcal F(L_0,0,\Delta)\subset\mathcal F(L_0,L_1,\Delta)$, the above lower bound implies
\begin{equation*}
    m_{\epsilon}^{\mathrm{rand}}(L_0,L_1,\Delta,\sigma,p)
    \ge \Omega\left(\bigg(\frac{\sigma^{\frac{p}{p-1}}}{\epsilon^{\frac{p}{p-1}}}+1 \bigg)\frac{L_0\Delta}{\epsilon^2}\right).
\end{equation*}
Combining the result of Theorem \ref{thm:L1-lower-bound}, we know that 
for any given $p\in(1,2]$, there exists numerical constant $c=\min\{\hat c, \tilde c\}$ such that for all $L_0,L_1,\Delta,\sigma>0$, and~$\epsilon\le\hat c\min\{\sqrt{L_0\Delta},L_1\Delta\}$, it holds
\begin{equation*}
\begin{aligned}
    m_{\epsilon}^{\mathrm{rand}}
    (L_0,L_1,\Delta,\sigma,p)
    \ge  \Omega\left(\bigg(\frac{\sigma^{\frac{p}{p-1}}}{\epsilon^{\frac{p}{p-1}}}+1\bigg)\bigg(\frac{L_0\Delta}{\epsilon^2}+\frac{L_1\Delta}{\epsilon}\bigg)\right).
\end{aligned}
\end{equation*}
This finishes the proof.

\label{lem:sym-smooth}
If $f$ is $(L_0,L_1)$-smooth, then it holds
\begin{align}\label{eq:smooth-descent}
    f({\bf{y}}) \leq f({\bf{x}}) + \left\langle \nabla f({\bf{x}}), {\bf{y}}-{\bf{x}} \right\rangle + \frac{L_0+L_1\left\| \nabla f({\bf{x}}) \right\|}{2}\left\| {\bf{y}}-{\bf{x}} \right\|^2
\end{align}
for all ${\bf{x}},{\bf{y}}\in{\mathbb{R}}^d$ with $\left\| {\bf{y}}-{\bf{x}} \right\|\leq 1/L_1$.

\label{lem:normalize}
For all $\gamma \geq 0$, ${\bf{g}},{\bf{h}}\in{\mathbb{R}}^d$, it holds
\begin{align*}
\langle {\bf{h}},\varphi_\gamma({\bf{g}})\rangle
\ge \|{\bf{h}}\|-2\|{\bf{g}}-{\bf{h}}\|-\gamma.        
\end{align*}

\label{lem:heavy-tailed} 
For Algorithm \ref{alg:sn-mb-sgd}, it holds that
\begin{align*}
    {\mathbb{E}}[\left\| {\bf{g}}_t-\nabla f({\bf{x}}_t) \right\|] \leq   \frac{2 \sqrt{2}\sigma}{b^{1-1 / p}}
\end{align*}

Recall that the stochastic gradient evaluation in the algorithm is 
\begin{align*}
    {\bf{g}}_t = \frac{1}{b}\sum_{i=1}^b  {\bf{g}}({\bf{x}}_t;Z_{t,i}),
    \qquad\text{where}~~ Z_{t,1},\dots,Z_{t,b}\overset{\mathrm{i.i.d}}\sim {\mathcal{Z}}.
\end{align*}
Hence, it holds
\begin{align}\label{eq:exp-dk}
\begin{split}    
     &   \mathbb{E}\left[\left\| {\bf{g}}_t-\nabla f({\bf{x}}_t) \right\|\right] \\
     = & \mathbb{E}\left[\left\| \sum_{i=1}^{b} \frac{1}{b}\left({\bf{g}}({\bf{x}}_t;Z_{t,i})-\nabla f({\bf{x}}_t)\right) \right\|\right]  \\
    \leq & 2 \sqrt{2} \mathbb{E}\left [\left(\frac{1}{b^{p}} \sum_{i=1}^{b}\left\| {\bf{g}}({\bf{x}}_t;Z_{t,i})-\nabla f({\bf{x}}_i) \right\|^{p}\right)^{1 / p}\right] \\
    = &\frac{2 \sqrt{2}}{b} \mathbb{E}\left[\left(\sum_{i=1}^{b}\left\| {\bf{g}}({\bf{x}}_t;Z_{t,i})-\nabla f({\bf{x}}_t) \right\|^{p}\right)^{1 / p}\right]\\
\leq & \frac{2 \sqrt{2}}{b} \left(\mathbb{E}\left[\sum_{i=1}^{b}\left\| {\bf{g}}({\bf{x}}_t;Z_{t,i})-\nabla f({\bf{x}}_t) \right\|^{p}\right]\right)^{1 / p}\\
   \leq  & \frac{2 \sqrt{2}}{b} \cdot b^{1 / p} \sigma= \frac{2 \sqrt{2}\sigma}{b^{1-1 / p}},
\end{split}
\end{align}
where the first inequality is based on Lemma 4.3 of  \citet{liu2025nonconvex},
second inequality is based on Jensen's inequality, and the last inequality is based on $p$-BCM assumption.
